func TestNormalizedPowerAndTSS(t *testing.T) {
	// Steady 200 W for an hour: NP 200, at FTP 200 the TSS is 100.
	tt := seconds(3601, 1)
	p := make([]float64, 3601)
	for i := range p {
		p[i] = 200
	}
	np := NormalizedPower(tt, p)
	if math.Abs(np-200) > 1e-9 {
		t.Fatalf("NP %v", np)
	}
	if tss := TSS(np, 200, 3600); math.Abs(tss-100) > 1e-9 {
		t.Errorf("TSS %v", tss)
	}
	// Alternating 0/400 W every 60 s: NP clearly above the 200 W average.
	for i := range p {
		p[i] = 0
		if i/60%2 == 1 {
			p[i] = 400
		}
	}
	if np := NormalizedPower(tt, p); np < 280 || np > 330 {
		t.Errorf("variable NP %v", np)
	}
	if NormalizedPower(tt[:20], p[:20]) != 0 || TSS(200, 0, 3600) != 0 {
		t.Error("short activity or missing FTP")
	}
}

func TestTRIMP(t *testing.T) {
	tt := seconds(601, 6) // one hour in 6 s steps
	hr := make([]float64, 601)
	for i := range hr {
		hr[i] = 150
	}
	// HRr = (150-50)/(190-50) = 0.714…; 60 min × HRr × 0.64 × e^(1.92 HRr)
	r := 100.0 / 140
	want := 60 * r * 0.64 * math.Exp(1.92*r)
	if got := TRIMP(tt, hr, 50, 190, false); math.Abs(got-want) > 1e-6 {
		t.Errorf("TRIMP %v, want %v", got, want)
	}
	if got, want := TRIMP(tt, hr, 50, 190, true), 60*r*0.86*math.Exp(1.67*r); math.Abs(got-want) > 1e-6 {
		t.Errorf("female TRIMP %v, want %v", got, want)
	}
	if TRIMP(tt, hr, 0, 190, false) != 0 {
		t.Error("needs resting HR")
	}
}

func TestZoneBoundsAndTimeInZones(t *testing.T) {
	hb := HRZoneBounds(190)
	if len(hb) != 6 || hb[0] != 95 || hb[5] != 190 {
		t.Errorf("hr bounds %v", hb)
	}
	pb := PowerZoneBounds(250)
	if len(pb) != 8 || pb[1] != 138 || pb[6] != 375 || pb[7] != 4000 {
		t.Errorf("power bounds %v", pb)
	}
	tt := []int64{0, 10, 20, 30, 100}
	got := TimeInZones(tt, series(90, 120, 200, nan, 130), hb)
	// 90 → below zone 1, 120 → zone 2 (114–133), 200 → above max → top zone.
	want := []float64{10, 0, 10, 0, 0, 10}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("zones %v, want %v", got, want)
		}
	}
	if TimeInZones(tt, series(nan, nan), hb) != nil {
		t.Error("no values, no zones")
	}
}
